# Generated by the Niobium FHE Application Design AI Assistant (FHEanna). — v0.13.0
"""
run_test reporter: three-tier evidence, in the methodology's order.

  (a) The decrypted scores: distribution and the case rate per score
      decile, which is what a PRS is used for.
  (b) LEAD — the application's own quality: the deployed (FHE) pipeline and
      the plaintext reference, each measured against the GROUND-TRUTH disease
      phenotype of the scored participants (AUC + high-risk enrichment, the
      metrics that matter for a risk score used to stratify a cohort).
  (c) Encryption fidelity — decrypted FHE scores vs the FAITHFUL TWIN
      (isolates encryption noise; the quantization cost is the twin-vs-
      reference row, known from Stage 7). This block is the PASS/FAIL exit
      code, gated on the Stage 7 recorded tolerance: a tiny numeric error AND
      zero changes to who is flagged high genetic risk.
  (d) Deployment profile — per-stage wall clock, peak server RSS, boundary
      sizes (from run_test's profile.txt).

Usage: compare_results.py <run_dir> <n_rec> <mode>
"""

import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import refmodel as R

TOL_FHE_TWIN = 1e-2   # Stage 7 recorded tolerance (score units); CKKS delivers ~1e-7
N_SLOTS = 32768
HIGH_RISK_FRAC = 0.10  # top decile = "high genetic risk"


def main():
    run_dir, n_rec, mode = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    here = os.path.dirname(os.path.abspath(__file__))
    ddir = os.path.join(here, "..", "data")

    n_markers = len(R.load_weights(os.path.join(ddir, "weights.csv"))["weight"])
    twin = _col(os.path.join(ddir, "twin_scores.csv"))[:n_rec]
    ref = _col(os.path.join(ddir, "reference_scores.csv"))[:n_rec]
    labels = R.load_labels(os.path.join(ddir, "labels.csv"))
    pheno = labels["phenotype"][:n_rec]

    n_batches = (n_rec + N_SLOTS - 1) // N_SLOTS
    fhe = []
    for k in range(n_batches):
        raw = np.fromfile(
            os.path.join(run_dir, "client_home", f"scores_batch_{k}.bin"))
        fhe.append(raw)                       # raw PRS — no rescale
    fhe = np.concatenate(fhe)[:n_rec]

    print()
    print("=" * 72)
    print(f"polygenic risk scoring, run report: mode {mode}, "
          f"{n_rec:,} participants")
    print("=" * 72)

    base = float(pheno.mean())

    # ---- (a) the scores themselves ----
    print(f"\n(a) DECRYPTED RISK SCORES: sum over {n_markers:,} markers of "
          f"dosage x weight")
    qs = np.percentile(fhe, [0, 10, 25, 50, 75, 90, 100])
    print("      " + "".join(f"{h:>9s}" for h in
                             ("min", "p10", "p25", "median", "p75", "p90", "max")))
    print("      " + "".join(f"{v:9.3f}" for v in qs))

    order = np.argsort(fhe)
    print(f"\n    {'decile':>6s} {'n':>6s} {'mean score':>12s} "
          f"{'cases':>7s} {'case rate':>10s}")
    n_dec = len(fhe) // 10
    for d in range(10):
        idx = order[d * n_dec:(d + 1) * n_dec] if d < 9 else order[9 * n_dec:]
        print(f"    {d + 1:6d} {len(idx):6d} {fhe[idx].mean():12.3f} "
              f"{int(pheno[idx].sum()):7d} {pheno[idx].mean():10.3f}")
    print(f"    {'all':>6s} {len(fhe):6d} {fhe.mean():12.3f} "
          f"{int(pheno.sum()):7d} {base:10.3f}")

    # ---- (b) application quality ----
    def quality(pred, name):
        auc = R.roc_auc(pred, pheno)
        flags = R.top_fraction_flags(pred, HIGH_RISK_FRAC)
        rate = float(pheno[flags].mean())
        print(f"  {name:<30s} AUC {auc:6.4f}   top-decile case rate {rate:5.3f} "
              f"({rate/base:.1f}x base)")

    print("\n(b) APPLICATION QUALITY vs ground-truth disease phenotype "
          f"(base rate {base:.3f})")
    quality(fhe, "deployed (encrypted) pipeline")
    quality(ref, "plaintext reference PRS")

    # ---- (b) encryption fidelity (the gate) ----
    d_twin = np.abs(fhe - twin)
    fhe_flags = R.top_fraction_flags(fhe, HIGH_RISK_FRAC)
    twin_flags = R.top_fraction_flags(twin, HIGH_RISK_FRAC)
    flips_twin = int(np.sum(fhe_flags != twin_flags))
    print("\n(c) ENCRYPTION FIDELITY")
    print(f"  FHE vs faithful twin:  max {d_twin.max():.3e}   "
          f"mean {d_twin.mean():.3e}   high-risk flips {flips_twin}   "
          f"(tolerance: max <= {TOL_FHE_TWIN})")
    ok = (d_twin.max() <= TOL_FHE_TWIN) and (flips_twin == 0)

    # ---- (c) deployment profile ----
    prof = os.path.join(run_dir, "profile.txt")
    print("\n(d) DEPLOYMENT PROFILE")
    if os.path.exists(prof):
        sizes = []
        for line in open(prof):
            parts = line.split()
            if not parts:
                continue
            if parts[0] in ("keygen", "encrypt", "decrypt"):
                print(f"  {parts[0]:<16s} batch {parts[1]:<3s} "
                      f"wall {parts[2]:>8s} s")
            elif parts[0].startswith("server"):
                rss = (f"   peak RSS {int(parts[3])/1048576:.2f} GiB"
                       if len(parts) > 3 and parts[3] != "-" else "")
                print(f"  {parts[0]:<16s} batch {parts[1]:<3s} "
                      f"wall {parts[2]:>8s} s{rss}")
            elif parts[0] in ("key", "upload", "download"):
                sizes.append(parts)
        if sizes:
            print("  boundary sizes:")
            for p in sizes:
                print(f"    {p[0]:<9s} {p[1]:<14s} "
                      f"{int(p[2])/1048576:8.1f} MiB")

    out = dict(mode=mode, n_rec=n_rec,
               fhe_vs_twin_max=float(d_twin.max()),
               fhe_vs_twin_mean=float(d_twin.mean()),
               high_risk_flips_vs_twin=flips_twin,
               auc_fhe=float(R.roc_auc(fhe, pheno)),
               auc_ref=float(R.roc_auc(ref, pheno)),
               passed=bool(ok))
    with open(os.path.join(run_dir, "compare_results.json"), "w") as fh:
        json.dump(out, fh, indent=2)

    print("\n  written")
    for rel in ([f"client_home/scores_batch_{k}.bin" for k in range(n_batches)]
                + ["compare_results.json", "profile.txt", "tools.log"]):
        path = os.path.join(run_dir, rel)
        if os.path.exists(path):
            print(f"    {os.path.relpath(path, os.path.dirname(here)):<46s}"
                  f"{_hsize(os.path.getsize(path)):>10s}")

    verdict = ("PASS. Encrypted pipeline reproduces the faithful twin within the "
               "recorded tolerance, zero high-risk reclassifications" if ok
               else "FAIL. Tolerance exceeded; see (c)")
    print("\n" + "=" * 72)
    print("RESULT: " + verdict)
    print("=" * 72)

    sys.exit(0 if ok else 1)


def _hsize(b):
    for unit in ("B", "KiB", "MiB", "GiB"):
        if b < 1024 or unit == "GiB":
            return f"{b:.0f} {unit}" if unit == "B" else f"{b:.1f} {unit}"
        b /= 1024


def _col(path, idx=1):
    import csv
    with open(path) as fh:
        r = csv.reader(fh)
        next(r)
        return np.array([float(row[idx]) for row in r])


if __name__ == "__main__":
    main()
